use std::collections::HashMap;
use std::net::IpAddr;
use std::path::PathBuf;
use std::sync::atomic::Ordering;
use std::time::Duration;

use anyhow::{Context, Result};
use clap::Parser;
use rtnp_cli::{fmt_summary, load_key, load_tls_client, load_tls_server, parse_duration};
use rtnp_core::log::LogSink;
use rtnp_core::receiver::{Receiver, ReceiverConfig, Shared};

/// Receive and measure traffic generated by rtnp-send.
#[derive(Parser)]
#[command(version, about)]
struct Args {
    /// Address to listen on (use :: for IPv6)
    #[arg(long, default_value = "0.0.0.0")]
    bind: IpAddr,
    #[arg(long, default_value_t = 8998)]
    udp_port: u16,
    #[arg(long, default_value_t = 8998)]
    tcp_port: u16,
    /// Also listen for stream-style SCTP on this port (needs kernel SCTP support)
    #[arg(long)]
    sctp_port: Option<u16>,
    #[arg(long, default_value_t = 8999)]
    control_port: u16,
    /// Answer SIP calls on this UDP port (off by default; 5060 is the usual one). Callers get the
    /// UDP data port in the SDP answer; SRTP keys sent in SDP (SDES) are accepted per call unless
    /// --srtp-key is set. A test endpoint, not a PBX: no registration or authentication
    #[arg(long)]
    sip_port: Option<u16>,
    /// Serve Prometheus metrics (GET /metrics) on this port
    #[arg(long)]
    metrics_port: Option<u16>,
    /// Disable the UDP listener
    #[arg(long)]
    no_udp: bool,
    /// Disable the TCP listener
    #[arg(long)]
    no_tcp: bool,
    /// Disable the control channel
    #[arg(long)]
    no_control: bool,
    /// Require control-channel peers to authenticate with this key (prefer RTNP_KEY or --key-file)
    #[arg(long, env = "RTNP_KEY", hide_env_values = true)]
    key: Option<String>,
    /// Read the shared key from a file
    #[arg(long)]
    key_file: Option<PathBuf>,
    /// Serve the control channel over TLS with this certificate chain (PEM). Needs --tls-key
    #[arg(long, requires = "tls_key")]
    tls_cert: Option<PathBuf>,
    /// Private key (PEM) for --tls-cert
    #[arg(long, requires = "tls_cert")]
    tls_key: Option<PathBuf>,
    /// Connect to --log-server over TLS, trusting the CA certificate(s) in this PEM file
    #[arg(long)]
    tls_ca: Option<PathBuf>,
    /// Let authenticated controllers make THIS host generate traffic (agent mode). Requires a key.
    /// Anyone holding the key can direct traffic from this host to any destination.
    #[arg(long)]
    allow_launch: bool,
    /// Answer two-way calls: send a constant RTP return stream to senders that ask for one
    /// (`rtnp-send --bidir`). Bounded to 64 streams, 10-200 ms cadence, and each goes only to
    /// the address its forward stream came from and stops 5 s after that stream goes quiet
    #[arg(long)]
    allow_reverse: bool,
    /// Expect SRTP (AES_CM_128_HMAC_SHA1_80) on the UDP port with this 30-byte master key and
    /// salt (60 hex or 40 base64 characters). Plain RTP and packets that fail authentication are
    /// dropped and counted as malformed. Prefer RTNP_SRTP_KEY or --srtp-key-file.
    #[arg(long, env = "RTNP_SRTP_KEY", hide_env_values = true)]
    srtp_key: Option<String>,
    /// Read the SRTP master key from a file
    #[arg(long)]
    srtp_key_file: Option<PathBuf>,
    /// Write per-packet JSONL records to this file
    #[arg(long, short = 'l')]
    log: Option<PathBuf>,
    /// Stream per-packet JSONL records to a rtnp-logd server (host:port)
    #[arg(long, conflicts_with = "log")]
    log_server: Option<String>,
    /// Name for this stream on the log server
    #[arg(long, default_value = "receiver")]
    log_tag: String,
    /// Live status interval (0s disables)
    #[arg(long, default_value = "1s", value_parser = parse_duration)]
    report_interval: Duration,
    /// Exit after the first sender session completes via the control channel
    #[arg(long)]
    one_shot: bool,
}

#[tokio::main]
async fn main() -> Result<()> {
    let args = Args::parse();
    let key = load_key(&args.key, &args.key_file)?;
    let sink = match (&args.log, &args.log_server) {
        (Some(p), _) => LogSink::to_file(p)
            .await
            .with_context(|| format!("cannot open log {}", p.display()))?,
        (None, Some(addr)) => LogSink::to_remote_with(
            addr,
            &args.log_tag,
            key.as_deref(),
            load_tls_client(&args.tls_ca)?.as_ref(),
        )
        .await
        .with_context(|| format!("cannot reach log server {addr}"))?,
        (None, None) => LogSink::none(),
    };
    let cfg = ReceiverConfig {
        bind: args.bind,
        udp_port: (!args.no_udp).then_some(args.udp_port),
        tcp_port: (!args.no_tcp).then_some(args.tcp_port),
        sctp_port: args.sctp_port,
        control_port: (!args.no_control).then_some(args.control_port),
        metrics_port: args.metrics_port,
        one_shot: args.one_shot,
        auth_key: key.clone(),
        allow_launch: args.allow_launch,
        allow_reverse: args.allow_reverse,
        sip_port: args.sip_port,
        tls: load_tls_server(&args.tls_cert, &args.tls_key)?,
        srtp_key: rtnp_core::srtp::load_key(
            args.srtp_key.as_deref(),
            args.srtp_key_file.as_deref(),
        )?,
    };
    let rx = Receiver::bind(cfg, sink.handle())
        .await
        .context("cannot start receiver")?;
    let off = || "off".to_string();
    eprintln!(
        "listening: udp={} tcp={} sctp={} control={} metrics={} sip={}",
        rx.udp_addr().map(|a| a.to_string()).unwrap_or_else(off),
        rx.tcp_addr().map(|a| a.to_string()).unwrap_or_else(off),
        rx.sctp_addr().map(|a| a.to_string()).unwrap_or_else(off),
        rx.control_addr().map(|a| a.to_string()).unwrap_or_else(off),
        rx.metrics_addr().map(|a| a.to_string()).unwrap_or_else(off),
        rx.sip_addr().map(|a| a.to_string()).unwrap_or_else(off),
    );
    if args.tls_cert.is_some() && rx.control_addr().is_some() {
        eprintln!("control channel: TLS");
    }
    if key.is_some() {
        eprintln!("control channel: authentication required");
    } else if rx.control_addr().is_some() {
        eprintln!(
            "warning: control channel is unauthenticated (set --key to require a shared key)"
        );
    }
    if args.allow_launch {
        eprintln!("agent mode: authenticated controllers may generate traffic from this host");
    }
    let shared = rx.shared();

    let live = (!args.report_interval.is_zero()).then(|| {
        let shared = shared.clone();
        let every = args.report_interval;
        tokio::spawn(async move { live_report(shared, every).await })
    });

    let ctrl_c = async {
        let _ = tokio::signal::ctrl_c().await;
    };
    let served = rx.serve(ctrl_c).await;
    if let Some(l) = live {
        l.abort();
    }

    let mut text = String::new();
    for ((session, flow), s) in shared.snapshot() {
        text.push_str(&format!("Flow {flow} (session {session:08x})\n"));
        fmt_summary(&mut text, &s, "  ");
    }
    if !text.is_empty() {
        println!("\n{text}");
    }
    let malformed = shared.malformed.load(Ordering::Relaxed);
    if malformed > 0 {
        eprintln!("ignored {malformed} malformed packets");
    }
    let overflow = shared.overflow.load(Ordering::Relaxed);
    if overflow > 0 {
        eprintln!("ignored {overflow} packets from flows beyond the tracking limit");
    }
    match sink.close().await {
        Ok(0) => {}
        Ok(dropped) => {
            eprintln!("warning: {dropped} log records dropped (disk or network too slow)")
        }
        Err(e) => eprintln!("warning: log delivery failed: {e}"),
    }
    served.context("receiver failed")
}

async fn live_report(shared: std::sync::Arc<Shared>, every: Duration) {
    let mut prev: HashMap<(u32, u32), (u64, u64)> = HashMap::new();
    let mut tick = tokio::time::interval(every);
    tick.tick().await;
    loop {
        tick.tick().await;
        let secs = every.as_secs_f64();
        for (key, s) in shared.snapshot() {
            let (pp, pb) = prev.insert(key, (s.packets, s.bytes)).unwrap_or((0, 0));
            if s.packets == pp {
                continue;
            }
            println!(
                "[{:08x}:{}] {:>9.1} kbit/s {:>8.1} pps  delay {:.3} ms  jitter {:.3} ms  lost {} ({:.2}%)",
                key.0,
                key.1,
                (s.bytes - pb) as f64 * 8.0 / 1000.0 / secs,
                (s.packets - pp) as f64 / secs,
                s.delay_avg_ms,
                s.jitter_ms,
                s.lost,
                s.loss_pct
            );
        }
    }
}
